mapper.select:
SELECT FROM t_opportunity o LEFT JOIN t_customer c ON o.customer_id = c.id LEFT JOIN t_user u ON o.owner_id = u.id LEFT JOIN t_product p ON o.product_id = p.id WHERE 1 = 1
AND o.owner_id = #{query.dataScopeUserId}
AND o.customer_id = #{query.customerId}
AND o.owner_id = #{query.ownerId}
AND o.stage = #{query.stage}
AND (o.opportunity_no LIKE CONCAT('%', #{query.keyword}, '%') OR c.customer_name LIKE CONCAT('%', #{query.keyword}, '%') OR o.requirement LIKE CONCAT('%', #{query.keyword}, '%'))
ORDER BY o.update_time DESC, o.id DESC

mapper.insert:
INSERT INTO t_opportunity (
    opportunity_no, customer_id, clue_id, owner_id, product_id, source_type,
    stage, requirement, expected_amount, expected_close_date, next_action_time,
    version, create_time, create_by, update_time, update_by
) VALUES (
    #{opportunityNo}, #{customerId}, #{clueId}, #{ownerId}, #{productId}, #{sourceType},
    #{stage}, #{requirement}, #{expectedAmount}, #{expectedCloseDate}, #{nextActionTime},
    #{version}, #{createTime}, #{createBy}, #{updateTime}, #{updateBy}
)

mapper.update:
UPDATE t_opportunity SET product_id = #{record.productId}, requirement = #{record.requirement}, expected_amount = #{record.expectedAmount}, expected_close_date = #{record.expectedCloseDate}, next_action_time = #{record.nextActionTime}, update_time = #{record.updateTime}, update_by = #{record.updateBy}, version = version + 1 WHERE id = #{record.id}
AND owner_id = #{dataScopeUserId}
AND stage NOT IN ('WON', 'LOST', 'CLOSED')
